#include <bits/stdc++.h>
using namespace std;

const int MOD = 100000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;
    cin >> n1 >> n2 >> k1 >> k2;

    if (n1 == 0 && n2 == 0) {
        cout << 1;
        return 0;
    }

    vector<vector<array<int, 2>>> dp(
        n1 + 1, vector<array<int, 2>>(n2 + 1, {0, 0})
    );

    for (int i = 1; i <= min(n1, k1); ++i)
        dp[i][0][0] = 1;

    for (int j = 1; j <= min(n2, k2); ++j)
        dp[0][j][1] = 1;

    for (int i = 1; i <= n1; ++i) {
        for (int j = 1; j <= n2; ++j) {
            long long ways1 = 0, ways2 = 0;

            for (int len = 1; len <= k1 && len <= i; ++len)
                ways1 += dp[i - len][j][1];

            for (int len = 1; len <= k2 && len <= j; ++len)
                ways2 += dp[i][j - len][0];

            dp[i][j][0] = ways1 % MOD;
            dp[i][j][1] = ways2 % MOD;
        }
    }

    cout << (dp[n1][n2][0] + dp[n1][n2][1]) % MOD;
    return 0;
}

