    static int dp[101][101][2];

    if (n1 == 0 && n2 == 0) {
        cout << 1;
        return 0;
    }

    for (int i = 0; i <= n1; ++i) {
        for (int j = 0; j <= n2; ++j) {
            for (int len = 1; len <= k1 && len <= i; ++len) {
                if (i == len && j == 0)
                    dp[i][j][0] = (dp[i][j][0] + 1) % MOD;
                else
                    dp[i][j][0] = (dp[i][j][0] + dp[i - len][j][1]) % MOD;
            }

            for (int len = 1; len <= k2 && len <= j; ++len) {
                if (i == 0 && j == len)
                    dp[i][j][1] = (dp[i][j][1] + 1) % MOD;
                else
                    dp[i][j][1] = (dp[i][j][1] + dp[i][j - len][0]) % MOD;
            }
        }
    }

    cout << (dp[n1][n2][0] + dp[n1][n2][1]) % MOD;
    return 0;
