#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 100000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;
    cin >> n1 >> n2 >> k1 >> k2;

    if (n1 == 0 && n2 == 0) {
        cout << 1;
        return 0;
    }

    vector<vector<vector<ll>>> dp1(
        n1 + 1, vector<vector<ll>>(n2 + 1, vector<ll>(k1 + 1))
    );
    vector<vector<vector<ll>>> dp2(
        n1 + 1, vector<vector<ll>>(n2 + 1, vector<ll>(k2 + 1))
    );

    if (n1 > 0 && k1 > 0) dp1[1][0][1] = 1;
    if (n2 > 0 && k2 > 0) dp2[0][1][1] = 1;

    for (int i = 0; i <= n1; ++i) {
        for (int j = 0; j <= n2; ++j) {
            for (int run = 1; run <= k1; ++run) {
                ll ways = dp1[i][j][run];
                if (!ways) continue;

                if (i < n1 && run < k1)
                    dp1[i + 1][j][run + 1] =
                        (dp1[i + 1][j][run + 1] + ways) % MOD;

                if (j < n2 && k2 > 0)
                    dp2[i][j + 1][1] =
                        (dp2[i][j + 1][1] + ways) % MOD;
            }

            for (int run = 1; run <= k2; ++run) {
                ll ways = dp2[i][j][run];
                if (!ways) continue;

                if (j < n2 && run < k2)
                    dp2[i][j + 1][run + 1] =
                        (dp2[i][j + 1][run + 1] + ways) % MOD;

                if (i < n1 && k1 > 0)
                    dp1[i + 1][j][1] =
                        (dp1[i + 1][j][1] + ways) % MOD;
            }
        }
    }

    ll answer = 0;
    for (int run = 1; run <= k1; ++run)
        answer = (answer + dp1[n1][n2][run]) % MOD;
    for (int run = 1; run <= k2; ++run)
        answer = (answer + dp2[n1][n2][run]) % MOD;

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 100000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n1, n2, k1, k2;
    cin >> n1 >> n2 >> k1 >> k2;

    vector<vector<int>> dp1(n1 + 1, vector<int>(n2 + 1));
    vector<vector<int>> dp2(n1 + 1, vector<int>(n2 + 1));

    for (int i = 1; i <= min(n1, k1); ++i)
        dp1[i][0] = 1;

    for (int j = 1; j <= min(n2, k2); ++j)
        dp2[0][j] = 1;

    for (int i = 1; i <= n1; ++i) {
        for (int j = 1; j <= n2; ++j) {
            for (int x = 1; x <= min(i, k1); ++x)
                dp1[i][j] = (dp1[i][j] + dp2[i - x][j]) % MOD;

            for (int x = 1; x <= min(j, k2); ++x)
                dp2[i][j] = (dp2[i][j] + dp1[i][j - x]) % MOD;
        }
    }

    if (n1 == 0 && n2 == 0)
        cout << 1;
    else
        cout << (dp1[n1][n2] + dp2[n1][n2]) % MOD;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 100000000;

ll memo[101][101][11][11];
int n1, n2, k1, k2;

ll f(int q1, int q2, int s1, int s2) {
    if (s1 > k1 || s2 > k2 || q1 > n1 || q2 > n2)
        return 0;
    if (q1 == n1 && q2 == n2)
        return 1;

    ll &res = memo[q1][q2][s1][s2];
    if (res != -1)
        return res;

    res = (f(q1 + 1, q2, s1 + 1, 0) +
           f(q1, q2 + 1, 0, s2 + 1)) % MOD;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n1 >> n2 >> k1 >> k2;
    memset(memo, -1, sizeof(memo));

    cout << f(0, 0, 0, 0);
    return 0;
}

